// Експертний контент: сумки, валізи, рюкзаки, чохли й рушники Butterfly (партія 2).
// Формат і правила — як у gearExpert.ts: лише факти виробника, без підписаних тренером
// оцінок і «думки експерта».
//
// ⚠️ ДЖЕРЕЛА (звірено 19.10.2026):
//  • butterfly-adria.com — офіційний дистрибʼютор Butterfly (Kitami, Kashiwa, Tokai, Easy,
//    Logo 2019, рушники: розміри, обʼєм, матеріал, відділення);
//  • teessport.com — фірмові описи Butterfly в архіві дилера (Otomo, Kanoy, Kaban, Yasyo,
//    Sendai Duffle, Kibako, Full Hard, 1950, Logo 2019, рушники Streak/Big Streak/Sign);
//  • revspin.net — Black Line Maxi, Tabi, Sendai Rolltop.
// Без даних виробника свідомо НЕМАЄ: валіза Black Line, чохол Black Line, Cell Case 1/2,
// BG Case, решта рушників — їхні картки закриті, доки не знайдемо фактів.
import type { ComparisonRow, ExpertEntry } from "./expert";

type L = { ua: string; ru: string };
const t = (ua: string, ru: string): L => ({ ua, ru });
const qa = (qua: string, qru: string, aua: string, aru: string) => ({ q: t(qua, qru), a: t(aua, aru) });
const sec = (tua: string, tru: string, bua: string, bru: string) => ({ title: t(tua, tru), body: t(bua, bru) });
const row = (slug: string, model: string, c1: L, c2: L, c3: L, fit: L): ComparisonRow => ({
  slug,
  model,
  cells: { c1, c2, c3 },
  fit,
});
type Body = Omit<ExpertEntry, "comparison" | "comparisonTitle" | "comparisonCols">;

